    if (node === null) {
      return 0;
    }
    const leftSum = subtreeSum(node.left);
    const rightSum = subtreeSum(node.right);
    total += Math.abs(leftSum - rightSum);
    return leftSum + rightSum + node.val;
  }

  subtreeSum(root);
  return total;
