function findTilt(root) {
  // For every node, add up each of its two subtrees from scratch with an explicit stack.
  const sumOf = (start) => {
    let sum = 0;
    const stack = start ? [start] : [];
    while (stack.length) {
      const node = stack.pop();
      sum += node.val;
      if (node.left) stack.push(node.left);
      if (node.right) stack.push(node.right);
    }
    return sum;
  };
  let answer = 0;
  const all = root ? [root] : [];
  while (all.length) {
    const node = all.pop();
    answer += Math.abs(sumOf(node.left) - sumOf(node.right));
    if (node.left) all.push(node.left);
    if (node.right) all.push(node.right);
  }
  return answer;
}

