function generate(rand, size) {
  const n = size === 'large' ? 850 + Math.floor(rand() * 100) : Math.floor(rand() * 12);
  if (n === 0) return [[]];
  // Attach each new node to a free child slot; a high bias keeps extending the newest slots,
  // which makes long, lopsided branches, while a low bias gives bushy trees.
  const bias = rand();
  const nodes = [{ val: 0, left: null, right: null }], slots = [[0, 'left'], [0, 'right']];
  for (let i = 1; i < n; i++) {
    const k = rand() < bias ? slots.length - 1 - Math.floor(rand() * Math.min(2, slots.length)) : Math.floor(rand() * slots.length);
    const [parent, side] = slots[k];
    slots[k] = slots[slots.length - 1];
    slots.pop();
    nodes[parent][side] = i;
    nodes.push({ val: 0, left: null, right: null });
    slots.push([i, 'left'], [i, 'right']);
  }
  const span = size === 'large' || rand() < 0.2 ? 1000 : 6;
  for (const node of nodes) node.val = Math.floor(rand() * (2 * span + 1)) - span;
  // Level-order serialisation with null for missing children, trailing nulls removed.
  const out = [], queue = [0];
  for (let q = 0; q < queue.length; q++) {
    if (queue[q] === null) { out.push(null); continue; }
    const node = nodes[queue[q]];
    out.push(node.val);
    queue.push(node.left, node.right);
  }
  while (out.length && out[out.length - 1] === null) out.pop();
  return [out];
}
